from produire import produire
from format_lecon import paras,table,steps
from medicaments import euthyrox
parts=[
('L’{hypothyroïdie est un déficit d’action des hormones thyroïdiennes}. Elle peut accompagner une somnolence, une prise de poids et des troubles respiratoires du sommeil. Le ronflement seul ne suffit pas à la suspecter fortement.',paras('La forme primaire provient de la thyroïde ; une forme centrale dépend de l’axe hypothalamo-hypophysaire. Cette distinction change l’interprétation des dosages et la surveillance.', 'NICE cite l’hypothyroïdie parmi les situations où les apnées sont plus fréquentes. Sa découverte ne prouve pas qu’elle soit la seule cause du trouble nocturne.')),
('Le {contexte oriente les causes et le dépistage ciblé}. Hashimoto, chirurgie, iode radioactif et certains médicaments sont des causes usuelles. Une histoire endocrinienne ou autoimmune rend le bilan plus pertinent.',paras('Les HUG mentionnent notamment amiodarone, lithium et certaines immunothérapies. Leur présence doit être transmise au médecin, sans arrêt spontané.', 'Une fatigue isolée est peu spécifique. Associer histoire, symptômes et biologie évite de prescrire une hormone pour un ronflement sans déficit démontré.')),
('Les {hormones thyroïdiennes règlent de nombreuses fonctions métaboliques}. Leur déficit ralentit plusieurs systèmes. La respiration nocturne peut être affectée par plusieurs mécanismes associés.',paras('La TSH hypophysaire stimule la thyroïde, et les hormones circulantes exercent un rétrocontrôle. Une TSH élevée peut traduire une insuffisance thyroïdienne primaire ; elle ne résume pas les atteintes centrales.', 'Le poids, les tissus des voies aériennes et la fonction ventilatoire peuvent participer au contexte de sommeil. L’amélioration hormonale ne garantit pas la disparition d’apnées déjà constituées.')),
('Les {alarmes imposent une évaluation générale urgente}. Trouble de conscience, hypothermie ou insuffisance ventilatoire ne relèvent pas d’une simple consultation pour ronflement. Une décompensation cardiaque demande aussi une prise en charge rapide.',paras('Une hypothyroïdie sévèrement décompensée nécessite un traitement hospitalier spécialisé. Le schéma oral de substitution chronique présenté plus loin n’est pas un protocole de réanimation.', 'Une insuffisance surrénalienne ou hypophysaire non traitée doit être recherchée selon le contexte avant la lévothyroxine. Introduire la substitution sans cette précaution peut être dangereux.')),
('L’{anamnèse recherche un ensemble de signes concordants}. Demander frilosité, constipation, ralentissement, peau sèche et prise de poids. Préciser antécédents thyroïdiens et médicaments.',paras('Noter grossesse ou projet de grossesse, pathologie cardiaque, symptômes d’autres déficits hypophysaires et compléments alimentaires. La biotine peut perturber certains dosages.', 'Si la personne est déjà traitée, vérifier prises, oublis, changements de spécialité et interactions alimentaires ou médicamenteuses. Fatigue et ronflement ne justifient pas une augmentation automatique de la dose.')),
('L’{examen apprécie état général et complications}. Observer fréquence cardiaque, pression, température et vigilance selon la présentation. Examiner le cou et rechercher une gêne compressive.',paras('Un goitre ou un nodule peut coexister sans expliquer le déficit hormonal. Une croissance rapide de masse, une dysphonie, une dyspnée ou une dysphagie demandent une évaluation dédiée.', 'L’examen nasal et pharyngé ainsi que l’évaluation pondérale restent utiles. Une étiquette endocrinienne ne dispense pas de rechercher un mécanisme anatomique d’apnées.')),
('L’{approche syndromique distingue déficit hormonal et autres fatigues}. Une maladie du sommeil, une dépression ou un médicament peuvent coexister. Les formes centrales réclament une interprétation particulière.',table(['Résultats ou contexte','Interprétation à vérifier'],[['TSH augmentée et T4 libre abaissée.','Hypothyroïdie primaire manifeste.'],['TSH augmentée et T4 libre normale.','Forme subclinique possible, à confirmer selon contexte.'],['T4 libre basse avec TSH non élevée de façon adaptée.','Atteinte centrale ou contexte interférent à examiner.'],['Valeurs discordantes avec clinique et prise de biotine.','Interférence analytique possible.'] ])),
('Le {diagnostic repose sur des dosages interprétés avec le contexte}. La TSH est un premier test chez l’adulte sans suspicion centrale. La T4 libre précise le statut hormonal.',paras('NICE recommande TSH et T4 libre ensemble si une atteinte hypophysaire est suspectée ou chez l’enfant. Une TSH apparemment normale ne doit donc pas exclure une hypothyroïdie centrale.', 'Une anomalie modérée isolée peut nécessiter confirmation. La maladie aiguë et certaines substances modifient les résultats ; éviter un diagnostic définitif sur une valeur discordante sans réévaluation.')),
('Les {examens complémentaires cherchent la cause utile à la décision}. Les anticorps anti-TPO peuvent documenter une origine autoimmune. Leur répétition n’est pas un outil de réglage de la dose.',paras('NICE propose les anticorps anti-TPO devant une TSH élevée, sans répétition de routine chez l’adulte. Une échographie répond à une anomalie structurale, pas à toute anomalie hormonale.', 'En cas de suspicion centrale, le bilan des autres axes et l’imagerie sont spécialisés. Une exploration du sommeil reste nécessaire si pauses ou symptômes persistent, même après correction hormonale.')),
('L’{algorithme confirme le déficit avant de substituer}. Identifier les urgences et les contre-indications. Adapter ensuite traitement et surveillance à la forme de maladie.',steps('Repérer décompensation respiratoire, neurologique ou cardiaque.', 'Confirmer le statut thyroïdien et distinguer forme primaire ou centrale.', 'Vérifier fonction surrénalienne selon le contexte, interactions et grossesse.', 'Introduire la substitution individualisée si indiquée ; suivre clinique et biologie.', 'Réévaluer séparément les apnées et la somnolence résiduelle.')),
('La {prise en charge suisse utilise la lévothyroxine lorsque la substitution est indiquée}. La dose est ajustée au terrain et aux analyses. Elle ne se calcule pas à partir de l’intensité du ronflement.',paras('Les HUG et NICE retiennent la lévothyroxine comme traitement de référence. Les chiffres ci-dessous viennent exclusivement de la notice suisse Euthyrox ; les schémas britanniques ne sont pas présentés comme des doses AIPS.', '@@MEDICAMENTS@@', 'Une hypothyroïdie subclinique n’entraîne pas automatiquement une prescription : tenir compte de la persistance biologique, des symptômes, de l’âge et du contexte. Une forme centrale exige une surveillance spécialisée qui ne repose pas sur la TSH seule.')),
('Le {suivi évite sous-traitement et excès hormonal}. Les ajustements nécessitent du temps avant leur plein effet. Une accélération cardiaque ou des signes d’excès doivent conduire à réévaluer.',paras('Vérifier symptômes, prises et analyses selon le calendrier prescrit. NICE recommande, dans les formes primaires adultes, des contrôles jusqu’à stabilité puis une surveillance régulière ; grossesse et formes centrales suivent un parcours distinct.', 'Le contrôle de l’hypothyroïdie ne permet pas d’arrêter automatiquement une pression positive. Un bilan du sommeil peut vérifier si des apnées restent présentes.')),
('Le {point clé est une substitution fondée sur un diagnostic hormonal}. Ronflement et fatigue ne sont pas spécifiques. La sécurité surrénalienne, cardiaque et obstétricale compte avant et pendant le traitement.',paras('Ne pas confondre microgrammes et milligrammes. Une normalisation biologique est un objectif endocrinien ; la sécurité respiratoire nocturne reste à évaluer pour elle-même.'))]
quiz=[('Le ronflement seul prouve-t-il l’hypothyroïdie ?','Non.'),('Quelle association biologique évoque une forme primaire manifeste ?','TSH élevée et T4 libre basse.'),('Une TSH normale exclut-elle une forme centrale ?','Non.'),('Que doser si une atteinte hypophysaire est suspectée ?','TSH et T4 libre, avec bilan spécialisé des autres axes selon contexte.'),('La biotine peut-elle perturber les résultats ?','Oui.'),('Une échographie est-elle obligatoire pour toute TSH élevée ?','Non.'),('Faut-il traiter une insuffisance surrénalienne avant la substitution thyroïdienne ?','Oui.'),('Les doses de lévothyroxine sont-elles en milligrammes ?','Non, en microgrammes.'),('Quand prend-on la dose entière selon la notice citée ?','Le matin à jeun, au moins une demi-heure avant le petit-déjeuner.'),('Le calcium ou le fer peuvent-ils réduire l’absorption ?','Oui.'),('La grossesse justifie-t-elle l’arrêt de la substitution ?','Non, la notice demande sa poursuite avec surveillance adaptée.'),('L’allaitement est-il incompatible avec Euthyrox dans la notice ?','Non.'),('Une forme subclinique impose-t-elle toujours un traitement ?','Non.'),('Le contrôle hormonal suffit-il à arrêter un traitement d’apnées ?','Non.')]
produire(8,parts,quiz,(1,4,14,16,19),euthyrox)
